int _runtime_queue_local_flush(int same_core, int fast_mode) {
    RuntimeEvent ev;
    memset(&ev, 0, sizeof(ev));
    g_runtime_event_base.fast_mode = fast_mode;

    if (same_core) {
        if (g_runtime_event_base.fast_mode) {
