        ev.wake_cnt++;
        ev.next = g_runtime_event_base.level_trigger_list;
        g_runtime_event_base.level_trigger_list = &ev;
        UNLOCK(&g_runtime_event_base.lock);
        return 0;
    }
    return -1;
}

